import QRCode from "qrcode";
import { appBaseUrl, paymentConfig } from "./config";
import type { Invoice } from "./types";

export function invoicePayUrl(invoiceId: string) {
  return `${appBaseUrl()}/pay/${invoiceId}`;
}

export function publicQrUrl(invoice: Invoice): string | null {
  if (!invoice.qrImageUrl) return null;
  if (invoice.qrImageUrl.startsWith("http")) return invoice.qrImageUrl;
  return `${appBaseUrl()}${invoice.qrImageUrl.startsWith("/") ? "" : "/"}${invoice.qrImageUrl}`;
}

export type PaymentQr = {
  kind: "upi" | "page" | "image";
  payload: string;
  note: string;
  upiId: string;
  payeeName: string;
  dataUrl: string;
  payUrl: string;
};

/**
 * Builds the QR shown on the pay page.
 * - Admin-uploaded QR image (invoice.qrImageUrl) takes priority.
 * - Otherwise a UPI deep link if PAYMENT_UPI_ID is set.
 * - Otherwise a QR pointing to the /pay page itself.
 */
export async function buildPaymentQrDataUrl(
  invoice: Invoice,
): Promise<PaymentQr> {
  const { upiId, payeeName, notePrefix } = paymentConfig();
  const payUrl = invoicePayUrl(invoice.id);
  const note = `${notePrefix}-${invoice.id.slice(0, 8)}`;

  const uploaded = publicQrUrl(invoice);
  if (uploaded) {
    return {
      kind: "image",
      payload: uploaded,
      note,
      upiId,
      payeeName,
      dataUrl: uploaded,
      payUrl,
    };
  }

  const useUpi = Boolean(upiId);
  const payload = useUpi
    ? `upi://pay?${new URLSearchParams({
        pa: upiId,
        pn: payeeName,
        am: invoice.amount.toFixed(2),
        cu: invoice.currency || "INR",
        tn: note,
      }).toString()}`
    : payUrl;

  const dataUrl = await QRCode.toDataURL(payload, {
    width: 280,
    margin: 2,
    errorCorrectionLevel: "M",
  });

  return {
    kind: useUpi ? "upi" : "page",
    payload,
    note,
    upiId,
    payeeName,
    dataUrl,
    payUrl,
  };
}
